    this._halfMoves++
    this._turn = them

    this._epSquare = EMPTY

    return
  }

  this._hash ^= this._epKey()
  this._hash ^= this._castlingKey()

  if (move.captured) {
    this._hash ^= this._pieceKey(move.to)
  }

