import { Chess } from './src/chess'

function attempt(label: string, fn: () => unknown) {
  try {
    const result = fn()
    console.log(`OK   ${label}:`, JSON.stringify(result))
  } catch (e) {
    console.log(`FAIL ${label}: ${e instanceof Error ? e.message : e}`)
  }
}

// reported repro: white pawn on promotion rank (rank 8)
attempt('white pawn h8, moves({square:h8, verbose:true})', () => {
  const chess = new Chess()
  chess.put({ type: 'p', color: 'w' } as never, 'h8')
  return chess.moves({ square: 'h8', verbose: true } as never)
})

// white pawn on a8 (other file on rank 8), non-verbose
attempt('white pawn a8, moves({square:a8})', () => {
  const chess = new Chess()
  chess.put({ type: 'p', color: 'w' } as never, 'a8')
  return chess.moves({ square: 'a8' } as never)
})

// black pawn on rank 1
attempt('black pawn h1, moves({square:h1, verbose:true})', () => {
  const chess = new Chess()
  chess.put({ type: 'p', color: 'b' } as never, 'h1')
  return chess.moves({ square: 'h1', verbose: true } as never)
})

// black pawn a1
attempt('black pawn a1, moves({square:a1})', () => {
  const chess = new Chess()
  chess.put({ type: 'p', color: 'b' } as never, 'a1')
  return chess.moves({ square: 'a1' } as never)
})

// all-moves generation with pawns on edge ranks (no square filter)
attempt('white pawn h8, all moves verbose', () => {
  const chess = new Chess()
  chess.put({ type: 'p', color: 'w' } as never, 'h8')
  return chess.moves({ verbose: true } as never).length
})

// control: normal pawn move still works
attempt('control: white pawn e2, moves({square:e2})', () => {
  const chess = new Chess()
  return chess.moves({ square: 'e2' } as never)
})

