    black.put({ type: 'p', color: 'b' }, 'a1')
    expect(black.moves({ square: 'a1', verbose: true })).toEqual([])
    expect(black.moves({ square: 'a1' })).toEqual([])
    expect(black.moves({ verbose: true })).toHaveLength(20)
  })
})

