  const moves = 'e8=N e8=B e8=R e8=Q'
  expect(chess.moves({ square: 'e7' })).to.have.members(split(moves))
})

test('moves - single square - promotion (white pawn on 7th rank, capture)', () => {
  const chess = new Chess('rr3k2/P7/8/8/8/8/8/2K5 w - - 0 1')
  const moves = 'b8=N b8=B b8=R+ b8=Q+'
  expect(chess.moves({ square: 'a7' })).to.have.members(split(moves))
})

